param([string]$RuntimeRoot=(Join-Path $env:LOCALAPPDATA "Executor"))
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;$sp=Join-Path $RuntimeRoot "direct-state.json";function S([int]$I,[string]$N){if($I-le0){return $true};$p=Get-CimInstance Win32_Process -Filter "ProcessId = $I" -ErrorAction SilentlyContinue;if(-not$p){return $true};if([string]$p.CommandLine-notlike"*$N*"){return $false};Stop-Process -Id $I -Force;return $true};if(Test-Path $sp){$x=Get-Content -Raw -Encoding UTF8 $sp|ConvertFrom-Json;if(-not(S ([int]$x.caddy_pid) "caddy")){throw "Caddy PID identity mismatch"};if([bool]$x.upnp_mapping_created){try{$m=(New-Object -ComObject HNetCfg.NATUPnP).StaticPortMappingCollection;if($m){$m.Remove([int]$x.public_port,"TCP")}}catch{}};if([bool]$x.firewall_rule_created){Remove-NetFirewallRule -DisplayName ([string]$x.firewall_rule_name) -ErrorAction SilentlyContinue}};&(Join-Path $PSScriptRoot "Stop-ExecutorControlPlane.ps1") -RuntimeRoot $RuntimeRoot;Remove-Item $sp -Force -ErrorAction SilentlyContinue;Write-Host "EXECUTOR DIRECT INGRESS STOPPED"